import type { EngineInterface, PluginOptions, Register } from 'claude-code'

type Violation = { rule: string; evidence: string; fix: string }
type Change = { file: string; text: string }
type Language = 'en' | 'ru'
type Settings = { mode: 'warn' | 'block'; model: string; includeUserRules: boolean; language: Language }

const RULE_FILES = ['CLAUDE.md', 'CLAUDE.local.md', '.claude/CLAUDE.md']
const MAX_CHANGE_CHARS = 20000
const MAX_RECENT = 5
const STOP_WAIT_MS = 8000
const MAIN = ''

const SYSTEM = `You review one change an AI coding agent just made to a file, against the project's rules from its CLAUDE.md files.
Judge only rules about what files contain: code style, naming, comments, structure, forbidden APIs or patterns, hardcoded values, where code belongs. Ignore rules about workflow, git, communication, tools, testing process or how the agent should behave.
Report a violation only when the NEW text clearly breaks a rule. Text the change removed or kept as it was is not a violation. When unsure, report nothing.
Answer with JSON only: {"violations":[{"rule":"the rule, quoted briefly","evidence":"the offending new text, short","fix":"what to change, one sentence"}]}. No violations: {"violations":[]}.`

const pluralRu = (count: number, one: string, few: string, many: string) => {
  const tens = count % 100
  const units = count % 10
  if (tens >= 11 && tens <= 14) return many
  if (units === 1) return one
  return units >= 2 && units <= 4 ? few : many
}

const TEXTS = {
  en: {
    commandDescription: 'Show which CLAUDE.md files the watchdog checks edits against, and what it caught',
    toast: (count: number, file: string) => `CLAUDE.md: ${count} rule${count === 1 ? '' : 's'} broken in ${file}`,
    header: (mode: string, model: string, running: number) =>
      `CLAUDE.md watchdog: ${mode} mode, checked by ${model}${running ? `, ${running} check${running === 1 ? '' : 's'} running` : ''}`,
    rulesFrom: 'Rules here come from:',
    noRules: 'No CLAUDE.md found from this folder up.',
    recent: 'Recently caught:',
    nothing: 'Nothing caught yet.',
    found: 'found',
    fix: 'fix',
  },
  ru: {
    commandDescription: 'Показать, по каким CLAUDE.md сторож проверяет правки и что он поймал',
    toast: (count: number, file: string) =>
      `CLAUDE.md: в ${file} ${pluralRu(count, 'нарушено', 'нарушены', 'нарушено')} ${count} ${pluralRu(count, 'правило', 'правила', 'правил')}`,
    header: (mode: string, model: string, running: number) =>
      `Сторож CLAUDE.md: режим ${mode}, проверяет ${model}${running ? `, проверок в работе: ${running}` : ''}`,
    rulesFrom: 'Правила здесь берутся из:',
    noRules: 'От этой папки вверх CLAUDE.md не найден.',
    recent: 'Недавние нарушения:',
    nothing: 'Пока ничего не поймано.',
    found: 'найдено',
    fix: 'исправить',
  },
} satisfies Record<Language, unknown>

const recent: { file: string; violations: Violation[] }[] = []
const notes = new Map<string, string[]>()
const pending = new Map<string, Set<Promise<void>>>()

const readSettings = (options: PluginOptions): Settings => ({
  mode: options.mode === 'block' ? 'block' : 'warn',
  model: typeof options.model === 'string' && options.model.trim() ? options.model.trim() : 'haiku',
  includeUserRules: options.includeUserRules === true,
  language: options.language === 'ru' ? 'ru' : 'en',
})

const parentOf = (path: string) => {
  const cut = path.replace(/\/+$/, '').lastIndexOf('/')
  return cut <= 0 ? '/' : path.slice(0, cut)
}

const baseName = (path: string) => path.slice(path.lastIndexOf('/') + 1)

const isRuleFile = (path: string) => RULE_FILES.some(name => path === name || path.endsWith(`/${name}`))

const ancestorsOf = (dir: string) => {
  const dirs = [dir]
  for (let at = dir; at !== '/'; ) dirs.push((at = parentOf(at)))
  return dirs.reverse()
}

const findRuleFiles = async ($: EngineInterface, dir: string, settings: Settings) => {
  const home = await $.env.get('HOME')
  const userRules = home ? `${home}/.claude/CLAUDE.md` : undefined
  const candidates = ancestorsOf(dir)
    .flatMap(at => RULE_FILES.map(name => `${at === '/' ? '' : at}/${name}`))
    .filter(path => path !== userRules)
  if (userRules && settings.includeUserRules) candidates.unshift(userRules)
  const found = await Promise.all(candidates.map(async path => ((await $.fs.exists(path)) ? path : undefined)))
  return [...new Set(found.filter((path): path is string => path !== undefined))]
}

const loadRules = async ($: EngineInterface, files: string[]) => {
  const parts = await Promise.all(
    files.map(async path => {
      const text = await $.fs.read(path)
      return typeof text === 'string' && text.trim() ? `# Rules from ${path}\n\n${text.trim()}` : undefined
    }),
  )
  return parts.filter(Boolean).join('\n\n')
}

const clip = (text: string) =>
  text.length > MAX_CHANGE_CHARS ? `${text.slice(0, MAX_CHANGE_CHARS)}\n[... ${text.length - MAX_CHANGE_CHARS} more characters]` : text

const describeEdit = (file: string, before: string, after: string): Change => ({
  file,
  text: `File: ${file}\n\nThe change replaced:\n<<<\n${clip(before)}\n>>>\nwith:\n<<<\n${clip(after)}\n>>>`,
})

const describeWrite = (file: string, content: string): Change => ({
  file,
  text: `File: ${file}\n\nThe change wrote the whole file:\n<<<\n${clip(content)}\n>>>`,
})

const parseViolations = (reply: string): Violation[] | undefined => {
  const json = reply.match(/\{[\s\S]*\}/)
  if (!json) return undefined
  try {
    const parsed: unknown = JSON.parse(json[0])
    const list = (parsed as { violations?: unknown }).violations
    if (!Array.isArray(list)) return undefined
    return list
      .filter((item): item is Record<string, unknown> => typeof item === 'object' && item !== null)
      .map(item => ({ rule: String(item.rule ?? ''), evidence: String(item.evidence ?? ''), fix: String(item.fix ?? '') }))
      .filter(item => item.rule)
  } catch {
    return undefined
  }
}

const inspect = async ($: EngineInterface, change: Change, settings: Settings) => {
  if (isRuleFile(change.file)) return []
  const files = await findRuleFiles($, parentOf(change.file), settings)
  if (files.length === 0) return []
  const rules = await loadRules($, files)
  if (!rules) return []
  const reply = await $.model.complete({
    model: settings.model,
    system: SYSTEM,
    prompt: [{ text: rules, cache: true }, { text: `\n\n# The change\n\n${change.text}` }],
    maxTokens: 1024,
    effort: 'low',
    timeoutMs: 30000,
  })
  return reply.isAnswered ? (parseViolations(reply.text) ?? []) : []
}

const describeViolations = (violations: Violation[], labels: { found: string; fix: string } = TEXTS.en) =>
  violations
    .map(v => `- ${v.rule}${v.evidence ? `\n  ${labels.found}: ${v.evidence}` : ''}${v.fix ? `\n  ${labels.fix}: ${v.fix}` : ''}`)
    .join('\n')

const remember = ($: EngineInterface, file: string, violations: Violation[], settings: Settings) => {
  recent.unshift({ file, violations })
  recent.splice(MAX_RECENT)
  $.ui.toast(TEXTS[settings.language].toast(violations.length, baseName(file)))
}

const noteFor = (file: string, violations: Violation[]) =>
  `rules-watchdog: your edit to ${file} breaks the project's CLAUDE.md rules.\n${describeViolations(violations)}\nFix this before moving on.`

const takeNotes = (loop: string) => {
  const list = notes.get(loop) ?? []
  notes.delete(loop)
  return list
}

const checkInBackground = ($: EngineInterface, loop: string, change: Change, settings: Settings) => {
  const running = pending.get(loop) ?? new Set<Promise<void>>()
  pending.set(loop, running)
  const done = new Promise<void>(resolve => {
    $.clock.after(0, () => {
      inspect($, change, settings)
        .then(violations => {
          if (violations.length === 0) return
          remember($, change.file, violations, settings)
          notes.set(loop, [...(notes.get(loop) ?? []), noteFor(change.file, violations)])
        })
        .catch(() => undefined)
        .finally(resolve)
    })
  })
  running.add(done)
  void done.then(() => running.delete(done))
}

const settle = async ($: EngineInterface, loop: string) => {
  const running = pending.get(loop)
  if (running?.size) {
    await Promise.race([Promise.all(running), $.clock.sleep(STOP_WAIT_MS).catch(() => undefined)])
  }
  return takeNotes(loop)
}

const countRunning = () => [...pending.values()].reduce((sum, running) => sum + running.size, 0)

export const register: Register = (on, options) => {
  const settings = readSettings(options)
  const texts = TEXTS[settings.language]

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'watchdog',
      description: texts.commandDescription,
    })
    return next(e)
  })

  on('command.run', { command: 'watchdog' }, async $ => {
    const files = await findRuleFiles($, await $.session.cwd(), settings)
    const running = countRunning()
    const lines = [
      texts.header(settings.mode, settings.model, running),
      files.length ? `${texts.rulesFrom}\n${files.map(path => `  ${path}`).join('\n')}` : texts.noRules,
      recent.length
        ? `${texts.recent}\n${recent.map(r => `  ${r.file}\n${describeViolations(r.violations, texts).replace(/^/gm, '    ')}`).join('\n')}`
        : texts.nothing,
    ]
    return { text: lines.join('\n\n') }
  })

  on('tool.call', async ($, e, next) => {
    const loop = e.agentId ?? MAIN
    const change =
      e.tool === 'Edit' ? describeEdit(e.file_path, e.old_string, e.new_string)
      : e.tool === 'Write' ? describeWrite(e.file_path, e.content)
      : undefined

    if (change && settings.mode === 'block') {
      const violations = await inspect($, change, settings)
      if (violations.length > 0) {
        remember($, change.file, violations, settings)
        return {
          deny: `rules-watchdog refused this edit to ${change.file}: it breaks the project's CLAUDE.md rules.\n${describeViolations(violations)}\nRedo the edit following these rules.`,
        }
      }
    }

    const ran = await next(e)
    if (ran.deny !== undefined) return ran
    if (change && settings.mode === 'warn' && !ran.isError) checkInBackground($, loop, change, settings)
    const delivered = takeNotes(loop)
    return delivered.length ? { ...ran, context: [...(ran.context ?? []), ...delivered] } : ran
  }).catch(($, e, next) => next(e))

  on('classic.Stop', async ($, e, next) => {
    const delivered = await settle($, MAIN)
    const result = await next(e)
    if (delivered.length === 0 || e.stop_hook_active || result.block !== undefined) return result
    return { ...result, block: delivered.join('\n\n') }
  }).catch(($, e, next) => next(e))

  on('classic.SubagentStop', async ($, e, next) => {
    const delivered = await settle($, e.agent_id)
    const result = await next(e)
    if (delivered.length === 0 || e.stop_hook_active || result.block !== undefined) return result
    return { ...result, block: delivered.join('\n\n') }
  }).catch(($, e, next) => next(e))
}

