{
  "name": "rules-watchdog",
  "version": "0.3.0",
  "description": "Checks every edit Claude makes against your CLAUDE.md rules and tells Claude what it broke",
  "author": {
    "name": "Darvl-52"
  },
  "repository": "https://github.com/Darvl-52/rules-watchdog",
  "license": "MIT",
  "userConfig": {
    "mode": {
      "type": "string",
      "title": "Mode",
      "description": "warn: let the edit land and tell Claude to fix it; block: refuse the edit before it lands",
      "default": "warn",
      "options": [
        "warn",
        "block"
      ]
    },
    "model": {
      "type": "string",
      "title": "Model",
      "description": "Model that checks the edits: an alias like haiku or a full model id",
      "default": "haiku"
    },
    "includeUserRules": {
      "type": "boolean",
      "title": "Include ~/.claude/CLAUDE.md",
      "description": "Also check edits against your personal CLAUDE.md",
      "default": false
    },
    "language": {
      "type": "string",
      "title": "Language",
      "description": "Language of the toasts and the /watchdog output: en or ru. Notes to Claude stay in English",
      "default": "en",
      "options": [
        "en",
        "ru"
      ]
    }
  }
}
